{"implementation":"def solve(case):
    lines = case.get("lines", [])
    trajectory = []
    state = "start"
    for i, line in enumerate(lines, start=1):
        if line.startswith("Thought: "):
            typ = "thought"
            content = line[9:]
        elif line.startswith("Action: "):
            typ = "action"
            content = line[8:]
        elif line.startswith("Observation: "):
            typ = "observation"
            content = line[13:]
        elif line.startswith("Final: "):
            typ = "final"
            content = line[7:]
        else:
            return {"error_line": i, "trajectory": trajectory, "valid": False}
        expected = {
            "start": {"thought"},
            "after_thought": {"action"},
            "after_action": {"observation"},
            "after_observation": {"thought", "final"},
            "after_final": set()
        }[state]
        if typ not in expected:
            return {"error_line": i, "trajectory": trajectory, "valid": False}
        trajectory.append({"type": typ, "content": content})
        if typ == "thought":
            state = "after_thought"
        elif typ == "action":
            state = "after_action"
        elif typ == "observation":
            state = "after_observation"
        elif typ == "final":
            state = "after_final"
    return {"error_line": None, "trajectory": trajectory, "valid": True}"}
